def is_prime(n):
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def find_prime_pairs(target):
    pairs = []
    # We only need to check up to target / 2
    for p in range(3, target // 2):
        if is_prime(p):
            r = target - p
            if is_prime(r):
                pairs.append((p, r))
    return pairs

pairs = find_prime_pairs(800)
print(f"Prime pairs (p, r) such that p + r = 800: {pairs}")

