def sieve(limit):
    primes = [True] * (limit + 1)
    primes[0] = primes[1] = False
    for start in range(2, int(limit**0.5) + 1):
        if primes[start]:
            for multiple in range(start**2, limit + 1, start):
                primes[multiple] = False
    return [i for i, is_prime in enumerate(primes) if is_prime]

def is_prime(n):
    if n < 2:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

# 1. Find all pairs (p, q) such that p + q = 800, p < q, p, q prime
primes_up_to_800 = sieve(800)
pq_pairs = []
for p in primes_up_to_800:
    if p >= 400:
        break
    q = 800 - p
    if q > p and is_prime(q):
        pq_pairs.append((p, q))

print(f"Found {len(pq_pairs)} pairs (p, q):")
# print(pq_pairs) # Keep this commented if the list is long

# 2. Iterate over pairs and find max r
max_r_overall = 0
results = {}

for p, q in pq_pairs:
    current_max_r = 0

    # r must be prime, q < r < 800 (r is odd since q is odd)
    # We search downwards from 799 to find the largest r first
    for r in reversed(primes_up_to_800):
        if r <= q:
            continue
        if r >= 800: # Should not happen given the list, but good practice
            continue

        # Check the four conditions
        S1 = 800 - r
        S2 = q + r - p
        S3 = r + p - q
        S4 = 800 + r

        # Since p, q are odd, S1 is odd. S2, S3, S4 are odd.
        # We must ensure none of them equals 2.

        if not is_prime(S1):
            continue
        if not is_prime(S2):
            continue
        if not is_prime(S3):
            continue
        if not is_prime(S4):
            continue

        # All conditions met!
        current_max_r = r
        break # Since we are iterating downwards, this is the maximum r for this (p, q) pair

    results[(p, q)] = current_max_r
    if current_max_r > max_r_overall:
        max_r_overall = current_max_r

print("\nResults for each (p, q):")
for pair, r_val in results.items():
    print(f"Pair {pair}: Max r found = {r_val}")

print(f"\nOverall maximum r: {max_r_overall}")

